# ---------- checks ----------
for t in T:
    gaps = sorted(int(g) for g in re.findall(r"\[(\d+)\]", t["text_el"]))
    if "extra_word" not in (t.get("example") or {}) and "reading-2" not in t["id"]:
        assert gaps == list(range(len(t["questions"]) + 1)), (t["id"], gaps)
    for q in t["questions"]:
        if q["options"] and q["answer"] not in "αβγδ": assert q["answer"] in q["options"], (t["id"], q)
    if t["id"].endswith("use-1"):
        assert len(t["questions"]) == 7
        for q in t["questions"]:
            assert any(re.search(r"(^|\s)" + q["answer"] + r"(\s|$)", l) for l in t["text_el"].split("\n")), q["answer"]
